<?php $title='Berita Desa'; require 'includes/header.php'; $q=trim($_GET['q']??''); $sql="SELECT * FROM posts WHERE status='publish'"; $params=[]; if($q){$sql.=' AND (judul LIKE ? OR isi LIKE ?)';$params=["%$q%","%$q%"];}$sql.=' ORDER BY tanggal DESC,id DESC';$st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll(); ?><section class="page-head"><div class="container"><h1 class="section-title">Berita Desa</h1><form class="row g-2 mt-3"><div class="col-md-8"><input name="q" value="<?=e($q)?>" class="form-control" placeholder="Cari berita..."></div><div class="col-md-2"><button class="btn btn-primary w-100">Cari</button></div></form></div></section><main class="container py-5"><div class="row g-4"><?php foreach($rows as $p):?><div class="col-md-4"><div class="card card-soft overflow-hidden"><?php if($p['gambar']):?><img src="<?=e($p['gambar'])?>" class="thumb w-100"><?php endif;?><div class="card-body"><small class="text-success"><?=e($p['kategori'])?> · <?=e($p['tanggal'])?></small><h5><?=e($p['judul'])?></h5><p class="text-muted"><?=e(mb_substr(strip_tags($p['isi']),0,130))?>...</p><a href="berita_detail.php?id=<?=$p['id']?>">Baca selengkapnya</a></div></div></div><?php endforeach;if(!$rows):?><div class="col-12"><div class="alert alert-light">Berita tidak ditemukan.</div></div><?php endif;?></div></main><?php require 'includes/footer.php'; ?>
